func parallelMap(items []int, f func(int) int) []int {
 results := make([]int, len(items))
 var wg sync.WaitGroup

 for i, v := range items {
 wg.Add(1)
 go func(idx, val int) {
 defer wg.Done()
 results[idx] = f(val) // 인덱스 다르므로 race 없음
 }(i, v)
 }

 wg.Wait()
 return results
}
```

